import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class StarDemo {

    private static final Logger log = Logger.getLogger(StarDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Checking STAR story readiness at " + BANK_NAME);

        StarEvaluator evaluator = new StarEvaluator();

        // Weak story: vague, team-voiced action, no number.
        StarStory weak = new StarStory(
                "Transfers were slow.",
                "",
                "We improved it somehow.",
                "It got better.",
                false);

        // Strong story: specific, first-person, quantified.
        StarStory strong = new StarStory(
                "Transfers for SAV2001 and CUR3001 took 2 seconds at peak, frustrating customers.",
                "I owned the performance of the transfer service.",
                "I profiled the path, found an N+1 query, and I added a batched fetch plus an index.",
                "I reduced median transfer latency from 2000ms to 180ms, a 91% improvement.",
                true);

        log.warning("Evaluating the WEAK story:");
        evaluator.evaluate(weak);

        log.info("Evaluating the STRONG story:");
        evaluator.evaluate(strong);
    }
}

// ─── Would be in model/StarStory.java in a real project ───
class StarStory {
    private final String situation;
    private final String task;
    private final String action;
    private final String result;
    private final boolean resultQuantified;

    StarStory(String situation, String task, String action, String result,
              boolean resultQuantified) {
        this.situation = situation;
        this.task = task;
        this.action = action;
        this.result = result;
        this.resultQuantified = resultQuantified;
    }

    String getSituation() { return situation; }
    String getTask() { return task; }
    String getAction() { return action; }
    String getResult() { return result; }
    boolean isResultQuantified() { return resultQuantified; }
}

// ─── Would be in eval/StarEvaluator.java in a real project ───
class StarEvaluator {
    private static final Logger log = Logger.getLogger(StarEvaluator.class.getName());

    int evaluate(StarStory s) {
        int score = 0;
        if (notBlank(s.getSituation())) {
            score++;
        } else {
            log.warning("Missing Situation — set the scene briefly.");
        }
        if (notBlank(s.getTask())) {
            score++;
        } else {
            log.warning("Missing Task — state YOUR specific responsibility.");
        }
        if (notBlank(s.getAction())) {
            score++;
            if (!s.getAction().contains("I ")) {
                log.warning("Action is not first-person — say what YOU did, not 'we'.");
            }
        } else {
            log.warning("Missing Action — describe the steps YOU took.");
        }
        if (notBlank(s.getResult()) && s.isResultQuantified()) {
            score++;
        } else {
            log.warning("Result not measurable — add a number (ms saved, % improved, errors reduced).");
        }
        final int finalScore = score;
        log.info(() -> "STAR completeness: " + finalScore + "/4 "
                + (finalScore == 4 ? "— interview ready." : "— needs work."));
        return score;
    }

    private boolean notBlank(String s) {
        return s != null && !s.trim().isEmpty();
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
